"""Confirmation broker (plan 10.2.4-5, 4A.3 voice hygiene).

* Confirmation text is generated by our code from the real plan, never from
  the model's own wording.
* Each request gets a single-use nonce and an expiry; late or repeated answers
  are ignored.
* Voice confirmation requires the strict phrase, must come from a *new*
  utterance (never the one that started the task) and is refused for Tier 2
  unless the user enabled it.
"""

from __future__ import annotations

import secrets
import threading
import time
from dataclasses import dataclass, field

from jarvis.events import bus
from jarvis.models import Plan, RiskTier


@dataclass
class PendingApproval:
    task_id: str
    nonce: str
    confirm_text: str
    tier: RiskTier
    origin_utterance_id: str
    expires: float
    event: threading.Event = field(default_factory=threading.Event)
    decision: str = "timeout"         # approve | deny | edit | timeout
    edit_text: str = ""
    channel: str = ""


def confirmation_text(plan: Plan, request_text: str) -> str:
    lines = [f"Request: {request_text.strip()[:200]}", f"Risk: Tier {int(plan.tier)} ({plan.tier.label})", "", "Steps:"]
    for s in plan.steps[:25]:
        badge = {0: "read", 1: "change", 2: "APPROVAL", 3: "FORBIDDEN"}[int(s.tier)]
        lines.append(f"  {s.number}. [{badge}] {s.text[:300]}")
    if len(plan.steps) > 25:
        lines.append(f"  ... and {len(plan.steps) - 25} more steps")
    if plan.targets:
        lines.append("")
        lines.append("Exact targets:")
        lines.extend(f"  - {t}" for t in plan.targets[:30])
    return "\n".join(lines)


def spoken_summary(plan: Plan) -> str:
    n = len(plan.steps)
    head = plan.summary or (plan.steps[0].text if plan.steps else "the task")
    return f"I have a {n}-step plan: {head[:90]}. Please review and approve on screen."


class ConfirmationBroker:
    def __init__(self, voice_allowed_for_tier2: bool = False, confirm_phrase: str = "confirm") -> None:
        self.voice_allowed_for_tier2 = voice_allowed_for_tier2
        self.confirm_phrase = confirm_phrase.lower().strip()
        self._pending: dict[str, PendingApproval] = {}
        self._lock = threading.Lock()

    def request(self, task_id: str, confirm_text: str, tier: RiskTier, origin_utterance_id: str,
                timeout_s: float = 120.0) -> PendingApproval:
        p = PendingApproval(task_id=task_id, nonce=secrets.token_hex(8), confirm_text=confirm_text, tier=tier,
                            origin_utterance_id=origin_utterance_id, expires=time.monotonic() + timeout_s)
        with self._lock:
            self._pending[p.nonce] = p
        bus.publish("approval_request", task_id=task_id, nonce=p.nonce, confirm_text=confirm_text,
                    tier=int(tier), timeout_s=timeout_s)
        return p

    def wait(self, p: PendingApproval) -> str:
        remaining = max(0.0, p.expires - time.monotonic())
        p.event.wait(remaining)
        with self._lock:
            self._pending.pop(p.nonce, None)
        bus.publish("approval_closed", task_id=p.task_id, nonce=p.nonce, decision=p.decision)
        return p.decision

    def _resolve(self, nonce: str, decision: str, channel: str, edit_text: str = "") -> bool:
        with self._lock:
            p = self._pending.get(nonce)
            if p is None or p.event.is_set() or time.monotonic() > p.expires:
                return False
            p.decision, p.channel, p.edit_text = decision, channel, edit_text
            p.event.set()
            self._pending.pop(nonce, None)
        return True

    def click(self, nonce: str, decision: str, edit_text: str = "") -> bool:
        """On-screen button / typed answer: always accepted for any tier < 3."""
        if decision not in ("approve", "deny", "edit"):
            return False
        return self._resolve(nonce, decision, "click", edit_text)

    def voice(self, utterance: str, utterance_id: str) -> bool:
        """Spoken answer. Returns True if it resolved a pending approval."""
        text = utterance.lower().strip(" .!?")
        with self._lock:
            candidates = [p for p in self._pending.values() if not p.event.is_set()]
        if not candidates:
            return False
        p = candidates[-1]
        if utterance_id == p.origin_utterance_id:
            return False   # the utterance that started the task can never confirm it
        if text in ("cancel", "deny", "no", "stop", "nahi", "mat karo", "ruko"):
            return self._resolve(p.nonce, "deny", "voice")
        if text == self.confirm_phrase or text == f"jarvis {self.confirm_phrase}":
            if p.tier >= RiskTier.CONSEQUENTIAL and not self.voice_allowed_for_tier2:
                bus.publish("say", text="For this action please click Approve on screen.")
                return True
            return self._resolve(p.nonce, "approve", "voice")
        return False

    def cancel_all(self) -> None:
        with self._lock:
            pending = list(self._pending.values())
            self._pending.clear()
        for p in pending:
            p.decision = "deny"
            p.event.set()

    def pending(self) -> list[PendingApproval]:
        with self._lock:
            return list(self._pending.values())
